describe('Empty State Illustration for Table with No Data', () => {
  beforeEach(() => {
    cy.visit('/table');
    cy.intercept('GET', '**/api/data', { statusCode: 200, body: [] }).as('emptyData');
  });

  it('should display empty state illustration when table has no data', () => {
    cy.wait('@emptyData');
    cy.get('[data-testid="table-container"]').should('be.visible');
    cy.get('[data-testid="empty-state-illustration"]').should('be.visible');
    cy.get('[data-testid="empty-state-title"]').should('contain', 'No Data Available');
    cy.get('[data-testid="empty-state-description"]').should('be.visible');
    cy.get('[data-testid="table-body"] tr').should('have.length', 0);
  });

  it('should hide empty state illustration when table has data', () => {
    cy.intercept('GET', '**/api/data', {
      statusCode: 200,
      body: [
        { id: 1, name: 'Item 1', status: 'Active' },
        { id: 2, name: 'Item 2', status: 'Inactive' }
      ]
    }).as('dataLoaded');

    cy.reload();
    cy.wait('@dataLoaded');
    cy.get('[data-testid="empty-state-illustration"]').should('not.exist');
    cy.get('[data-testid="table-body"] tr').should('have.length', 2);
  });

  it('should display empty state when all data is filtered out', () => {
    cy.intercept('GET', '**/api/data?search=nonexistent', {
      statusCode: 200,
      body: []
    }).as('filteredEmpty');

    cy.get('[data-testid="search-input"]').type('nonexistent');
    cy.wait('@filteredEmpty');
    cy.get('[data-testid="empty-state-illustration"]').should('be.visible');
    cy.get('[data-testid="empty-state-title"]').should('contain', 'No Results Found');
  });

  it('should verify empty state illustration is properly styled', () => {
    cy.wait('@emptyData');
    cy.get('[data-testid="empty-state-illustration"]')
      .should('be.visible')
      .and('have.css', 'display', 'flex')
      .and('have.css', 'justify-content', 'center')
      .and('have.css', 'align-items', 'center');

    cy.get('[data-testid="empty-state-icon"]')
      .should('be.visible')
      .and('have.attr', 'src')
      .and('include', 'empty-state');
  });
});
